function richestRoute(a: number[], b: number[]): number {
  const tracks = [a, b];
  const where = [new Map<number, number>(), new Map<number, number>()];
  a.forEach((v, i) => where[0].set(v, i));
  b.forEach((v, i) => where[1].set(v, i));
  const walk = (t: number, i: number): number => {
    const arr = tracks[t];
    if (i === arr.length) return 0;
    let best = arr[i] + walk(t, i + 1);
    const other = where[1 - t].get(arr[i]);
    if (other !== undefined) best = Math.max(best, arr[i] + walk(1 - t, other + 1));
    return best;
  };
  return Math.max(walk(0, 0), walk(1, 0)) % 1000000007;
}

