function richestRoute(a: number[], b: number[]): number {
  let i = 0, j = 0, sa = 0, sb = 0, total = 0;
  while (i < a.length && j < b.length) {
    if (a[i] < b[j]) sa += a[i++];
    else if (a[i] > b[j]) sb += b[j++];
    else {
      total += Math.max(sa, sb) + a[i]; // exact: stays far below 2^53
      sa = sb = 0;
      i++; j++;
    }
  }
  while (i < a.length) sa += a[i++];
  while (j < b.length) sb += b[j++];
  return (total + Math.max(sa, sb)) % 1000000007;
}

